/* @lc app=leetcode id=907 lang=kotlin */ class Solution { fun sumSubarrayMins(arr: IntArray): Int = LongArray(arr.size).let { dp -> java.util.ArrayDeque<Int>().let { st -> arr.indices.fold(0L) { acc, i -> generateSequence { st.peekFirst()?.takeIf { arr[it] >= arr[i] } }.forEach { _ -> st.pollFirst() }.let { (st.peekFirst() ?: -1).let { p -> (((if (p >= 0) dp[p] else 0L) + arr[i].toLong() * (i - p)) % 1_000_000_007).also { dp[i] = it }.also { st.addFirst(i) } } }.let { (acc + it) % 1_000_000_007 } } } }.toInt() }